95	function githubUrlBase(repo: string): { owner: string; name: string } | null {
96	  const url = git(repo, ["remote", "get-url", "origin"])?.trim() ?? "";
97	  const m = /github\.com[:/]([^/]+)\/([^/]+?)(?:\.git)?$/.exec(url);
98	  return m ? { owner: m[1]!, name: m[2]! } : null;
99	}
