117	const cleanModel = (m: string) => m.replace(/\[[^\]]*\]$/, "");
118	const WRAPPER_RE = /<(task-notification|system-reminder)\b[^>]*>[\s\S]*?<\/\1>/g;
119	/** A user row's text minus injected wrappers (background-task notifications, system reminders). */
120	const stripInjected = (s: string) => s.replace(WRAPPER_RE, "").trim();
121	
122	/** Project/Local rules files in an instructions or nested_memory attachment. */
123	function attachedRules(a: Json): { path: string; content: string }[] {
124	  const cands: Json[] = Array.isArray(a.files) ? [...a.files] : [];
125	  if (a.content && typeof a.content === "object") cands.push(a.content);
126	  if (typeof a.path === "string" && typeof a.content === "string") cands.push(a);
127	  return cands
128	    .filter((f) => (f.type === "Project" || f.type === "Local") && typeof f.path === "string" && typeof f.content === "string")
129	    .map((f) => ({ path: f.path as string, content: f.content as string }));
130	}
131	
132	function relToCwd(path: string, cwd: string | null): string {
133	  const root = cwd?.replace(/\/+$/, "");
134	  if (root && path.startsWith(`${root}/`)) return path.slice(root.length + 1);
135	  return path.replace(/^<repo>\//, "");
